package com.sobrenaturaldirector.mutation.validation;
import java.util.*;import com.sobrenaturaldirector.mutation.model.*;
public final class MutationPlanValidator {private MutationPlanValidator(){}public static List<String> validate(MutationTransactionPlan p){List<String>e=new ArrayList<String>();if(p==null)return Collections.singletonList("transaction missing");Map<String,MutationIntent>m=new HashMap<String,MutationIntent>();int edges=0,destructive=0,verify=0;for(MutationIntent i:p.getIntents()){if(m.put(i.getId(),i)!=null)e.add("duplicate intent "+i.getId());edges+=i.getDependencies().size();if(i.getMutationClass()==MutationClass.DESTRUCTIVE||i.getMutationClass()==MutationClass.REPLACEMENT)destructive++;if(i.getType()==MutationIntentType.VERIFY)verify++;if((i.getMutationClass()==MutationClass.DESTRUCTIVE||i.getMutationClass()==MutationClass.REPLACEMENT)&&!i.getRollback().isSnapshotRequired())e.add("destructive intent lacks snapshot "+i.getId());for(String d:i.getDependencies())if(!m.containsKey(d)&&!containsId(p.getIntents(),d))e.add("dependency missing "+d);}if(p.getBudget()!=null){if(p.getIntents().size()>p.getBudget().getMaxIntents())e.add("intent budget exceeded");if(edges>p.getBudget().getMaxEdges())e.add("edge budget exceeded");if(destructive>p.getBudget().getDestructiveCount())e.add("destructive budget exceeded");if(verify>p.getBudget().getMaxVerifications())e.add("verification budget exceeded");}if(new HashSet<String>(p.getDeterministicOrder()).size()!=p.getDeterministicOrder().size())e.add("duplicate topological order entry");if(p.getDeterministicOrder().size()!=p.getIntents().size())e.add("incomplete topological order");if(!e.contains("dependency cycle")){Map<String,Integer>state=new HashMap<String,Integer>();for(MutationIntent i:p.getIntents())if(cycle(i,m,state))e.add("dependency cycle");}return e;}private static boolean containsId(Collection<MutationIntent>x,String id){for(MutationIntent i:x)if(i.getId().equals(id))return true;return false;}private static boolean cycle(MutationIntent i,Map<String,MutationIntent>m,Map<String,Integer>s){Integer v=s.get(i.getId());if(v!=null)return v==1;s.put(i.getId(),1);for(String d:i.getDependencies()){MutationIntent x=m.get(d);if(x!=null&&cycle(x,m,s))return true;}s.put(i.getId(),2);return false;}}
